'Яркость поверхности': 'Surface brightness',
'Отставание действует на эффекты, которые идут во времени (волны, вихри, глитч и другие): тень повторяет их с задержкой.': 'The lag affects effects that run in time (waves, swirls, glitch and others): the shadow repeats them with a delay.',
'Время как форма': 'Time as form',
'Прошлые кадры видео становятся объёмом, время уходит третьей осью. Остаются только движущиеся места, и движение застывает скульптурой: идущий человек превращается в след из своих поз': 'Past video frames become a volume, with time as the third axis. Only the moving parts stay, and motion freezes into a sculpture: a walking person turns into a trail of their poses',
'Что остаётся в скульптуре': 'What stays in the sculpture',
'Движение': 'Motion',
