'Куда уходит время': 'Where time goes',
'Вглубь': 'Into depth',
'Вверх': 'Up',
'Вбок': 'Sideways',
'Длина скульптуры': 'Sculpture length',
'Старое гаснет': 'Old fades',
'Окраска по времени': 'Color by time',
'Точек в скульптуре': 'Points in the sculpture',
'Работает на видео из «Медиа» (не вместе с «Раскадровкой»). Скульптура набирается, пока видео играет. Вид «Движение» лучше всего на видео, где что-то движется на спокойном фоне.': 'Works on the video from Media (not together with Storyboard). The sculpture builds up while the video plays. Motion works best on a video where something moves against a calm background.',
'Пиксельная сортировка': 'Pixel sort',
'Приём глитч-арта: в каждой строке кадра точки светлых (или тёмных) участков пересортировываются по яркости и стекают полосами. Сортировка живая: держится, бежит волной, дышит или вспыхивает на ударе': 'A glitch-art technique: in each row of the frame, points of light (or dark) areas are re-sorted by brightness and run in streaks. The sort is alive: it holds, travels as a wave, breathes or flashes on the beat',
'Куда текут полосы': 'Streak direction',
