'Только для видео: человек или другой движущийся объект выделяется, за ним тянется шлейф из прошлых кадров, а видео плавно едет в сторону. Для объёма кадров включите «Объём по глубине»': 'Video only: a person or another moving object is picked out and a trail of past frames follows it while the video slides sideways. Turn on Depth volume for volume in the frames',
'Яркость фона текущего кадра': 'Brightness of the current frame background',
