'Цветоделение': 'Color split',
'Красный, зелёный и синий каналы видео расходятся: каждый берётся из своего момента времени или со своего места. Движение обрастает цветной бахромой, как у призмы': 'The red, green and blue channels of the video drift apart: each comes from its own moment or its own place. Motion grows a colored fringe, like through a prism',
