'Экспериментальный эффект: точки поднимаются в четвёртое измерение, там поворачиваются и возвращаются обратно. Форма выворачивается через бесконечность, течёт по сцепленным окружностям (расслоение Хопфа), кувыркается и дышит': 'Експериментальний ефект: точки піднімаються в четвертий вимір, там обертаються й повертаються назад. Форма вивертається через нескінченність, тече зчепленими колами (розшарування Гопфа), перекидається і дихає',
'Выворот': 'Виворіт',
'форма уходит в бесконечность и возвращается наизнанку': 'форма йде в нескінченність і повертається навиворіт',
