'Гасить улетевшие в бесконечность': 'Гасити точки, що полетіли в нескінченність',
'Со скоростью 0 форма замирает: поворот в 4D задаётся ползунком. Попробуйте вместе с «Эхом» (копии отстают в четвёртом измерении) и «Связями».': 'Зі швидкістю 0 форма завмирає: поворот у 4D задається повзунком. Спробуйте разом з «Відлунням» (копії відстають у четвертому вимірі) і «Зв’язками».',
'Эффект: Гиперпространство': 'Ефект: Гіперпростір',
'Через 4D': 'Через 4D',
'Модель выворачивается через четвёртое измерение и бесконечность, на изнанке подменяется новой и возвращается уже ею. Больше одного оборота: путь по расслоению Хопфа': 'Модель вивертається через четвертий вимір і нескінченність, на виворіті підміняється новою і повертається вже нею. Більше одного оберту: шлях розшаруванням Гопфа',
'Закручивать': 'Закручувати',
'Мышь отталкивает, притягивает или закручивает точки вихрем. Настраиваются радиус и действие': 'Миша відштовхує, притягує або закручує точки вихором. Налаштовуються радіус і дія',
'Объём': 'Об’єм',
'Включите «Объём по глубине» в разделе «Фото и видео»: каждый кадр выдавится по своей карте глубины.': 'Увімкніть «Об’єм за глибиною» в розділі «Фото й відео»: кожен кадр видавиться за своєю картою глибини.',
'Объём остальных кадров': 'Об’єм решти кадрів',
'Видео раскладывается на кадры, кадры собираются в блок из точек. Текущий кадр рисуется густо, остальные реже. Что сейчас показано, задаёт таймлайн внизу: играйте и перематывайте видео, блок следует за ним. Остальные эффекты работают поверх блока, «Объём по глубине» выдавливает каждый кадр по его карте глубины.': 'Відео розкладається на кадри, кадри збираються в блок із точок. Поточний кадр малюється густо, решта рідше. Що зараз показано, задає таймлайн унизу: грайте й перемотуйте відео, блок іде за ним. Інші ефекти працюють поверх блоку, «Об’єм за глибиною» видавлює кожен кадр за його картою глибини.',
'Раскадровка: у каждого кадра своя карта по яркости, светлое ближе. Для настоящей глубины выберите «Нейросеть».': 'Розкадрування: у кожного кадру своя карта за яскравістю, світле ближче. Для справжньої глибини виберіть «Нейромережа».',
'Раскадровка: нейросеть посчитала глубину всех кадров ({}).': 'Розкадрування: нейромережа порахувала глибину всіх кадрів ({}).',
'Раскадровка: нейросеть считает глубину кадров, {} из {}. Остальные пока по яркости.': 'Розкадрування: нейромережа рахує глибину кадрів, {} з {}. Решта поки за яскравістю.',
'кадры не рисовались (вкладка была скрыта)': 'кадри не малювалися (вкладку було приховано)',
