'Гравитационная линза': 'Гравітаційна лінза',
'Перед формой невидимая чёрная дыра: всё за ней искривляется, форма растягивается в кольцо Эйнштейна, в центре тёмный круг. Массу можно водить курсором или пустить по орбите': 'Перед формою невидима чорна діра: усе за нею викривлюється, форма розтягується в кільце Ейнштейна, у центрі темне коло. Масу можна водити курсором або пустити по орбіті',
