'Искривляется взгляд, а не сама форма: точки остаются на местах, но видны так, как будто свет прошёл рядом с массой. Со звуком масса пульсирует.': 'Викривлюється погляд, а не сама форма: точки лишаються на місцях, але видно їх так, ніби світло пройшло поруч із масою. Зі звуком маса пульсує.',
'Тень на стене': 'Тінь на стіні',
'Форма отбрасывает тень из точек на пол или стену. Свет можно водить по кругу, тень может отставать во времени, колыхаться, как от свечи, или светиться цветом палитры и модели': 'Форма кидає тінь із точок на підлогу або стіну. Світло можна водити по колу, тінь може відставати в часі, колихатися, як від свічки, або світитися кольором палітри й моделі',
