'Отставание действует на эффекты, которые идут во времени (волны, вихри, глитч и другие): тень повторяет их с задержкой.': 'Відставання діє на ефекти, що йдуть у часі (хвилі, вихори, глітч та інші): тінь повторює їх із затримкою.',
'Время как форма': 'Час як форма',
'Прошлые кадры видео становятся объёмом, время уходит третьей осью. Остаются только движущиеся места, и движение застывает скульптурой: идущий человек превращается в след из своих поз': 'Минулі кадри відео стають об’ємом, час іде третьою віссю. Лишаються тільки рухомі місця, і рух застигає скульптурою: людина, що йде, перетворюється на слід зі своїх поз',
