'Работает на видео из «Медиа» (не вместе с «Раскадровкой»). Скульптура набирается, пока видео играет. Вид «Движение» лучше всего на видео, где что-то движется на спокойном фоне.': 'Працює на відео з «Медіа» (не разом із «Розкадруванням»). Скульптура набирається, поки відео грає. Вид «Рух» найкраще на відео, де щось рухається на спокійному тлі.',
'Пиксельная сортировка': 'Піксельне сортування',
'Приём глитч-арта: в каждой строке кадра точки светлых (или тёмных) участков пересортировываются по яркости и стекают полосами. Сортировка живая: держится, бежит волной, дышит или вспыхивает на ударе': 'Прийом гліч-арту: у кожному рядку кадру точки світлих (або темних) ділянок пересортовуються за яскравістю й стікають смугами. Сортування живе: тримається, біжить хвилею, дихає або спалахує на ударі',
