'Форма идёт за громкостью: тихо это прежняя форма, громко это следующая. Дошла до конца, закрепилась, и после затишья начинается путь к следующей.': 'Форма йде за гучністю: тихо це попередня форма, гучно це наступна. Дійшла до кінця, закріпилась, і після затишшя починається шлях до наступної.',
