'Яркость поверхности': 'Brillo de la superficie',
'Отставание действует на эффекты, которые идут во времени (волны, вихри, глитч и другие): тень повторяет их с задержкой.': 'El retraso afecta a los efectos que avanzan en el tiempo (ondas, remolinos, glitch y otros): la sombra los repite con demora.',
'Время как форма': 'El tiempo como forma',
'Прошлые кадры видео становятся объёмом, время уходит третьей осью. Остаются только движущиеся места, и движение застывает скульптурой: идущий человек превращается в след из своих поз': 'Los fotogramas pasados se vuelven volumen, con el tiempo como tercer eje. Solo quedan las partes en movimiento y el movimiento se congela en escultura: una persona que camina se convierte en una estela de sus poses',
'Что остаётся в скульптуре': 'Qué queda en la escultura',
