'Работает на видео из «Медиа» (не вместе с «Раскадровкой»). Скульптура набирается, пока видео играет. Вид «Движение» лучше всего на видео, где что-то движется на спокойном фоне.': 'Funciona con el vídeo de Medios (no junto con Storyboard). La escultura se acumula mientras el vídeo se reproduce. Movimiento funciona mejor en un vídeo donde algo se mueve sobre un fondo tranquilo.',
'Пиксельная сортировка': 'Ordenación de píxeles',
'Приём глитч-арта: в каждой строке кадра точки светлых (или тёмных) участков пересортировываются по яркости и стекают полосами. Сортировка живая: держится, бежит волной, дышит или вспыхивает на ударе': 'Una técnica del glitch art: en cada fila del fotograma los puntos de las zonas claras (u oscuras) se reordenan por brillo y escurren en franjas. La ordenación está viva: se mantiene, corre como una ola, respira o destella en el golpe',
