'Когда выбранные частоты громче порога, форма переходит к следующей': 'Cuando las frecuencias elegidas superan el umbral, la forma pasa a la siguiente',
'Форма идёт за громкостью: тихо это прежняя форма, громко это следующая': 'La forma sigue el volumen: en silencio es la anterior, fuerte es la siguiente',
'Форма идёт за громкостью: тихо это прежняя форма, громко это следующая. Дошла до конца, закрепилась, и после затишья начинается путь к следующей.': 'La forma sigue el volumen: en silencio es la anterior, fuerte es la siguiente. Al llegar al final se fija, y tras una calma empieza el camino a la siguiente.',
'Всплеск выбранных частот переключает форму на следующую.': 'Un golpe en las frecuencias elegidas cambia a la siguiente forma.',
