'С каждой стороны форма выглядит по-своему. Крутите сцену или включите вращение формы: виды сменяют друг друга по кругу.': 'Cada lado muestra la forma de otro modo. Gira la escena o activa la rotación de la forma: las vistas se suceden en círculo.',
