'Яркость кадра превращается в карту высот: светящиеся контуры, как на топографической карте, по слоям в глубину. Работает с фото и видео.': 'El brillo del fotograma se convierte en un mapa de alturas: contornos luminosos como en un mapa topográfico, por capas en profundidad. Funciona con fotos y vídeo.',
'Линии': 'Líneas',
'Уровни': 'Niveles',
'Уровней': 'Niveles',
'Яркая каждая': 'Resaltar cada',
'Бег уровней': 'Barrido de niveles',
'Глубина слоёв': 'Profundidad de capas',
'Ближе': 'Más cerca',
'Только для видео: человек или другой движущийся объект выделяется, за ним тянется шлейф из прошлых кадров, а видео плавно едет в сторону. Для объёма кадров включите «Объём по глубине»': 'Solo para vídeo: una persona u otro objeto en movimiento se destaca y tras él se arrastra una estela de fotogramas pasados mientras el vídeo se desliza hacia un lado. Activa Volumen por profundidad para dar volumen a los fotogramas',
'Яркость фона текущего кадра': 'Brillo del fondo del fotograma actual',
'Чтобы кадры шлейфа выдавились по карте глубины, включите «Объём по глубине» отдельно.': 'Para extruir los fotogramas de la estela con un mapa de profundidad, activa Volumen por profundidad por separado.',
'Цветоделение': 'Separación de color',
'Красный, зелёный и синий каналы видео расходятся: каждый берётся из своего момента времени или со своего места. Движение обрастает цветной бахромой, как у призмы': 'Los canales rojo, verde y azul del vídeo se separan: cada uno viene de su propio momento o de su propio lugar. El movimiento gana un borde de color, como con un prisma',
'Как расходятся каналы': 'Cómo se separan los canales',
'Во времени': 'En el tiempo',
'В пространстве': 'En el espacio',
'Разнос': 'Separación',
'Разнос во времени, кадров': 'Separación en el tiempo, fotogramas',
'Разнос в пространстве, ячеек': 'Separación en el espacio, celdas',
'Вращение разноса, градусов в секунду': 'Rotación de la separación, grados por segundo',
'Работает на видео из «Медиа» (не вместе с «Раскадровкой»). Прошлое набирается, пока видео играет.': 'Funciona con el vídeo de Medios (no junto con Guion gráfico). El pasado se acumula mientras el vídeo se reproduce.',
'Рельеф движения': 'Relieve del movimiento',
'Всё, что движется в кадре, выступает из плоскости: чем сильнее изменилась точка за последние кадры, тем выше она поднимается и ярче горит. Неподвижное уходит в тень': 'Todo lo que se mueve en el fotograma sale del plano: cuanto más cambió un punto en los últimos fotogramas, más sube y más brilla. Lo quieto cae en sombra',
'Куда уходит движение': 'Hacia dónde va el movimiento',
'Рассыпается': 'Se dispersa',
'Порог шума': 'Umbral de ruido',
'Размер движущихся точек': 'Tamaño de los puntos en movimiento',
'Приглушить неподвижное': 'Atenuar lo quieto',
'Окраска палитрой': 'Tinte de paleta',
'Форма раскалывается, осколки падают на пол с отскоками и собираются обратно. Режим «Крошится» разрушает форму или видео под музыку': 'La forma se rompe, los trozos caen al suelo rebotando y se reúnen de nuevo. El modo «Se desmigaja» destruye la forma o el vídeo con la música',
