'Эксперименты': 'Experimente',
'Гиперпространство': 'Hyperraum',
'Экспериментальный эффект: точки поднимаются в четвёртое измерение, там поворачиваются и возвращаются обратно. Форма выворачивается через бесконечность, течёт по сцепленным окружностям (расслоение Хопфа), кувыркается и дышит': 'Experimenteller Effekt: Punkte steigen in die vierte Dimension, drehen sich dort und kehren zurück. Die Form stülpt sich durch die Unendlichkeit um, fließt entlang verketteter Kreise (Hopf-Faserung), überschlägt sich und atmet',
'Выворот': 'Umstülpen',
'форма уходит в бесконечность и возвращается наизнанку': 'die Form geht ins Unendliche und kehrt umgestülpt zurück',
'Расслоение Хопфа': 'Hopf-Faserung',
'точки текут по сцепленным окружностям': 'Punkte fließen entlang verketteter Kreise',
'Кувырок': 'Überschlag',
'двойное вращение в 4D': 'Doppelrotation in 4D',
'выворот туда и обратно': 'Umstülpen hin und zurück',
'Поворот в 4D, °': 'Drehung in 4D, °',
'Кривизна пространства': 'Raumkrümmung',
'Рывок на удар': 'Ruck auf den Beat',
'Цвет из четвёртого измерения': 'Farbe aus der vierten Dimension',
'Гасить улетевшие в бесконечность': 'Ins Unendliche entflogene Punkte ausblenden',
'Со скоростью 0 форма замирает: поворот в 4D задаётся ползунком. Попробуйте вместе с «Эхом» (копии отстают в четвёртом измерении) и «Связями».': 'Bei Geschwindigkeit 0 erstarrt die Form, der Regler bestimmt die 4D-Drehung. Probiere es mit Echo (die Kopien hinken in der vierten Dimension hinterher) und Verbindungen.',
'Эффект: Гиперпространство': 'Effekt: Hyperraum',
'Через 4D': 'Durch 4D',
'Модель выворачивается через четвёртое измерение и бесконечность, на изнанке подменяется новой и возвращается уже ею. Больше одного оборота: путь по расслоению Хопфа': 'Das Modell stülpt sich durch die vierte Dimension und die Unendlichkeit um, wird auf der Rückseite gegen das neue getauscht und kehrt als dieses zurück. Mehr als eine Umdrehung: der Weg folgt der Hopf-Faserung',
'Закручивать': 'Verwirbeln',
'Мышь отталкивает, притягивает или закручивает точки вихрем. Настраиваются радиус и действие': 'Die Maus stößt Punkte ab, zieht sie an oder verwirbelt sie. Radius und Aktion sind einstellbar',
'Объём': 'Volumen',
'Включите «Объём по глубине» в разделе «Фото и видео»: каждый кадр выдавится по своей карте глубины.': 'Schalte Volumen nach Tiefe unter Foto und Video ein: Jedes Bild wird nach seiner eigenen Tiefenkarte herausgedrückt.',
'Объём остальных кадров': 'Volumen der übrigen Bilder',
'Видео раскладывается на кадры, кадры собираются в блок из точек. Текущий кадр рисуется густо, остальные реже. Что сейчас показано, задаёт таймлайн внизу: играйте и перематывайте видео, блок следует за ним. Остальные эффекты работают поверх блока, «Объём по глубине» выдавливает каждый кадр по его карте глубины.': 'Das Video wird in Bilder zerlegt, die Bilder werden zu einem Block aus Punkten gestapelt. Das aktuelle Bild wird dicht gezeichnet, die übrigen lockerer. Die Zeitleiste unten bestimmt, was zu sehen ist: Spiele und spule das Video, der Block folgt. Andere Effekte wirken auf dem Block, Volumen nach Tiefe drückt jedes Bild nach seiner Tiefenkarte heraus.',
'Раскадровка: у каждого кадра своя карта по яркости, светлое ближе. Для настоящей глубины выберите «Нейросеть».': 'Storyboard: Jedes Bild hat seine eigene Helligkeitskarte, Helles ist näher. Für echte Tiefe wähle Neuronales Netz.',
'Раскадровка: нейросеть посчитала глубину всех кадров ({}).': 'Storyboard: Das neuronale Netz hat die Tiefe aller Bilder berechnet ({}).',
'Раскадровка: нейросеть считает глубину кадров, {} из {}. Остальные пока по яркости.': 'Storyboard: Das neuronale Netz berechnet die Tiefe der Bilder, {} von {}. Der Rest nutzt vorerst die Helligkeit.',
'кадры не рисовались (вкладка была скрыта)': 'es wurden keine Bilder gezeichnet (der Tab war ausgeblendet)',
