'Эти эффекты работают только с открытым видео и появляются вместе с ним.': 'Diese Effekte funktionieren nur mit einem geöffneten Video und erscheinen zusammen damit.',
'Эти эффекты работают только с открытым фото или видео и появляются вместе с ним.': 'Diese Effekte funktionieren nur mit einem geöffneten Foto oder Video und erscheinen zusammen damit.',
'Эти эффекты работают только у модели с анимацией и появляются вместе с ней.': 'Diese Effekte funktionieren nur bei einem Modell mit Animation und erscheinen zusammen damit.',
'Эти эффекты работают только с открытым видео, фото или анимацией и появляются вместе с ними.': 'Diese Effekte funktionieren nur mit einem geöffneten Video, Foto oder einer Animation und erscheinen zusammen damit.',
'Фигуры Хладни': 'Chladni-Figuren',
'Как песок на звенящей пластине: точки сбегаются на узловые линии стоячей волны и складываются в симметричный узор. Меняется нота, и песок перебегает в новый узор': 'Wie Sand auf einer klingenden Platte: Punkte laufen auf die Knotenlinien einer stehenden Welle und bilden ein symmetrisches Muster. Ändert sich der Ton, wandert der Sand in ein neues Muster',
'Что меняет узор': 'Was das Muster ändert',
'Высота звука': 'Tonhöhe',
'низкие ноты: мало линий, высокие: много': 'tiefe Töne: wenige Linien, hohe: viele',
'Удары': 'Beats',
'на каждый удар новый узор': 'bei jedem Beat ein neues Muster',
'Таймер': 'Timer',
'сам по кругу': 'wechselt von selbst im Kreis',
'Один узор': 'Ein Muster',
'выбранный номер': 'die gewählte Nummer',
'Узор': 'Muster',
'Новый узор раз в, с': 'Neues Muster alle, s',
'Как быстро песок перебегает, с': 'Wie schnell der Sand wandert, s',
'Мельче или крупнее узор': 'Feineres oder gröberes Muster',
'Дрожь песка': 'Sandzittern',
'Без звука узор меняется сам по таймеру. На фото и видео узор ложится на плоскость, на модели обходит её поверхность.': 'Ohne Ton wechselt das Muster per Timer. Auf Foto und Video liegt es auf der Ebene, auf einem Modell folgt es der Oberfläche.',
'Гравитационная линза': 'Gravitationslinse',
'Перед формой невидимая чёрная дыра: всё за ней искривляется, форма растягивается в кольцо Эйнштейна, в центре тёмный круг. Массу можно водить курсором или пустить по орбите': 'Ein unsichtbares Schwarzes Loch vor der Form: Alles dahinter wird gekrümmt, die Form dehnt sich zu einem Einsteinring mit dunklem Kreis in der Mitte. Bewege die Masse mit dem Cursor oder schicke sie in eine Umlaufbahn',
'Где масса': 'Wo die Masse ist',
'В центре': 'In der Mitte',
'За курсором': 'Folgt dem Cursor',
'По орбите': 'In Umlaufbahn',
'Масса (размер кольца)': 'Masse (Ringgröße)',
'Свечение кольца': 'Ringleuchten',
'Радиус орбиты': 'Bahnradius',
'Скорость орбиты': 'Bahngeschwindigkeit',
'Искривляется взгляд, а не сама форма: точки остаются на местах, но видны так, как будто свет прошёл рядом с массой. Со звуком масса пульсирует.': 'Der Blick wird gekrümmt, nicht die Form: Punkte bleiben an ihrem Platz, wirken aber, als ginge das Licht an der Masse vorbei. Mit Ton pulsiert die Masse.',
'Тень на стене': 'Schatten an der Wand',
'Форма отбрасывает тень из точек на пол или стену. Свет можно водить по кругу, тень может отставать во времени, колыхаться, как от свечи, или светиться цветом палитры и модели': 'Die Form wirft einen Schatten aus Punkten auf den Boden oder eine Wand. Das Licht kann im Kreis wandern, der Schatten zeitlich nachhinken, wie bei einer Kerze flackern oder in Paletten- und Modellfarben leuchten',
'Куда падает': 'Fällt auf',
