'Отставание действует на эффекты, которые идут во времени (волны, вихри, глитч и другие): тень повторяет их с задержкой.': 'Die Verzögerung wirkt auf Effekte, die in der Zeit laufen (Wellen, Wirbel, Glitch und andere): Der Schatten wiederholt sie verzögert.',
'Время как форма': 'Zeit als Form',
'Прошлые кадры видео становятся объёмом, время уходит третьей осью. Остаются только движущиеся места, и движение застывает скульптурой: идущий человек превращается в след из своих поз': 'Vergangene Videobilder werden zu einem Volumen, die Zeit ist die dritte Achse. Nur bewegte Stellen bleiben, und Bewegung erstarrt zur Skulptur: Ein gehender Mensch wird zu einer Spur seiner Posen',
