'Работает на видео из «Медиа» (не вместе с «Раскадровкой»). Скульптура набирается, пока видео играет. Вид «Движение» лучше всего на видео, где что-то движется на спокойном фоне.': 'Funktioniert mit dem Video aus Medien (nicht zusammen mit Storyboard). Die Skulptur entsteht, während das Video läuft. Bewegung wirkt am besten bei einem Video, in dem sich etwas vor ruhigem Hintergrund bewegt.',
'Пиксельная сортировка': 'Pixel-Sortierung',
'Приём глитч-арта: в каждой строке кадра точки светлых (или тёмных) участков пересортировываются по яркости и стекают полосами. Сортировка живая: держится, бежит волной, дышит или вспыхивает на ударе': 'Eine Glitch-Art-Technik: In jeder Bildzeile werden die Punkte heller (oder dunkler) Bereiche nach Helligkeit umsortiert und laufen in Streifen. Die Sortierung lebt: Sie hält, läuft als Welle, atmet oder blitzt auf den Beat',
