'Форма стягивается в шар, шар перетекает и раскрывается уже новой формой': 'Die Form zieht sich zu einer Kugel zusammen, die Kugel fließt über und öffnet sich als neue Form',
'Кубики': 'Blöcke',
'Форма распадается на блоки, блоки подпрыгивают и уходят по очереди, каждый в свой момент': 'Die Form zerfällt in Blöcke, die Blöcke hüpfen und gehen nacheinander, jeder zu seinem Zeitpunkt',
'Сплющивание': 'Abflachen',
'Форма схлопывается в плоскость, плоскость перетекает в новую и расправляется': 'Die Form klappt zu einer Ebene zusammen, die Ebene fließt in die neue und entfaltet sich',
'Что открыть': 'Was öffnen',
'Всё это можно добавить к тому, что уже есть, и потом делать между ними морфинг. Видео или фото одно: новое заменит прежнее.': 'Das lässt sich alles zum Vorhandenen hinzufügen und dann dazwischen morphen. Es gibt nur ein Video oder Foto: ein neues ersetzt das alte.',
'Модель': 'Modell',
