'По музыке': 'Zur Musik',
'Слушает': 'Hört auf',
'Скачок': 'Sprung',
'Когда выбранные частоты громче порога, форма переходит к следующей': 'Wenn die gewählten Frequenzen lauter als die Schwelle sind, wechselt die Form zur nächsten',
'Форма идёт за громкостью: тихо это прежняя форма, громко это следующая': 'Die Form folgt der Lautstärke: leise ist die alte Form, laut die nächste',
'Форма идёт за громкостью: тихо это прежняя форма, громко это следующая. Дошла до конца, закрепилась, и после затишья начинается путь к следующей.': 'Die Form folgt der Lautstärke: leise ist die alte Form, laut die nächste. Am Ende angekommen, bleibt sie, und nach einer Pause beginnt der Weg zur nächsten.',
'Всплеск выбранных частот переключает форму на следующую.': 'Ein Ausschlag in den gewählten Frequenzen schaltet auf die nächste Form um.',
'Не чаще, чем раз в': 'Nicht öfter als alle',
