'Ближние первыми: по карте глубины (видео и фото)': 'Nahe zuerst: nach Tiefenkarte (Video und Foto)',
'Дальние первыми: по карте глубины (видео и фото)': 'Ferne zuerst: nach Tiefenkarte (Video und Foto)',
'Включите музыку или микрофон и подождите пару секунд: порог подбирается по тому, что слышит морфинг': 'Schalte Musik oder Mikrofon ein und warte ein paar Sekunden: die Schwelle wird nach dem gewählt, was der Morph hört',
'Порядок форм': 'Reihenfolge der Formen',
'Рельеф (нейросеть)': 'Relief (neuronales Netz)',
'Для видео и фото: кадр вспухает объёмом по карте глубины от нейросети, слои отслаиваются от ближних к дальним': 'Für Video und Foto: das Bild wölbt sich nach der neuronalen Tiefenkarte auf, Schichten lösen sich von nah nach fern',
'3D-печать': '3D-Druck',
'Старая форма стекает в печатающую головку, новая печатается слой за слоем снизу вверх': 'Die alte Form fließt in einen Druckkopf, die neue wird Schicht für Schicht von unten gedruckt',
'Портал': 'Portal',
'Точки по спирали затягивает в светящееся кольцо, и из него же выходит новая форма': 'Punkte werden spiralförmig in einen leuchtenden Ring gezogen, aus dem die neue Form kommt',
'Стекло': 'Glas',
'Форма трескается на осколки, они кувыркаются и падают, потом осколки новой формы складываются в неё': 'Die Form zerspringt in Scherben, die taumeln und fallen, dann setzen sich Scherben der neuen Form zusammen',
'Магнит': 'Magnet',
'Точки идут пучками по дугам силовых линий, как железные опилки': 'Punkte ziehen in Bündeln entlang von Feldlinienbögen, wie Eisenspäne',
'Построить глубину нейросетью': 'Tiefe mit neuronalem Netz erstellen',
'Нейросеть строит карту глубины для каждого видео и фото из списка. Первый раз загружается модель': 'Das neuronale Netz erstellt für jedes Video und Foto der Liste eine Tiefenkarte. Beim ersten Mal wird das Modell geladen',
'Глубина от нейросети готова для всех видео и фото.': 'Die neuronale Tiefe ist für alle Videos und Fotos bereit.',
'Пока карты нет, глубина берётся по яркости кадра.': 'Solange keine Karte da ist, kommt die Tiefe aus der Bildhelligkeit.',
'Добавьте в морфинг видео или фото: глубина строится для них': 'Füge dem Morph ein Video oder Foto hinzu: die Tiefe wird für sie erstellt',
'Карта глубины готова: переход пойдёт по ней': 'Tiefenkarte bereit: der Übergang folgt ihr',
'Отметьте минимум две формы: модели, видео или фото. Добавить их можно выше, в разделе «Форма».': 'Wähle mindestens zwei Formen: Modelle, Videos oder Fotos. Hinzufügen kannst du sie oben unter «Form».',
