'Шлейф движения': 'Bewegungsspur',
'Только для видео: человек или другой движущийся объект выделяется, за ним тянется шлейф из прошлых кадров, а видео плавно едет в сторону. Работает вместе с «Объёмом по глубине»': 'Nur für Video: eine Person oder ein anderes bewegtes Objekt wird herausgelöst, ihm folgt eine Spur vergangener Bilder, und das Video gleitet zur Seite. Wirkt zusammen mit Tiefenvolumen',
