'Объём и точки': 'Volumen und Punkte',
'«Объём по глубине» включается вместе с шлейфом: каждый кадр выдавливается по своей карте глубины.': 'Tiefenvolumen schaltet sich mit der Spur ein: jedes Bild wird nach seiner eigenen Tiefenkarte herausgedrückt.',
'Объём кадров шлейфа': 'Volumen der Spurbilder',
'Размер точек шлейфа': 'Punktgröße der Spur',
