'Откройте видео: шлейф строится по его кадрам.': 'Öffne ein Video: die Spur entsteht aus seinen Bildern.',
'Выделяется то, что движется в кадре. Подходит, когда камера в ролике стоит на месте.': 'Hervorgehoben wird, was sich im Bild bewegt. Passt, wenn die Kamera im Clip stillsteht.',
'Выделяется ближнее по карте глубины: чем выше чувствительность, тем дальше граница.': 'Hervorgehoben wird Nahes nach der Tiefenkarte: je höher die Empfindlichkeit, desto weiter die Grenze.',
'Нейросеть выделения работает: объект ищется на каждом кадре шлейфа.': 'Das Auswahlnetz läuft: das Objekt wird in jedem Spurbild gesucht.',
'Нейросеть выделения не загрузилась ({}). Пока выделяется то, что движется.': 'Das Auswahlnetz wurde nicht geladen ({}). Vorerst wird hervorgehoben, was sich bewegt.',
'Загружаю нейросеть выделения (около 3 МБ, один раз). Пока выделяется то, что движется.': 'Lade das Auswahlnetz (etwa 3 MB, einmalig). Vorerst wird hervorgehoben, was sich bewegt.',
'Нейросеть выделения загрузится при включении (около 3 МБ, нужен интернет). Кадры никуда не отправляются.': 'Das Auswahlnetz lädt beim Einschalten (etwa 3 MB, Internet nötig). Bilder werden nirgendwohin gesendet.',
