'Только для видео: человек или другой движущийся объект выделяется, за ним тянется шлейф из прошлых кадров, а видео плавно едет в сторону. Для объёма кадров включите «Объём по глубине»': 'Nur für Video: Eine Person oder ein anderes bewegtes Objekt wird hervorgehoben, ihm folgt eine Spur aus vergangenen Bildern, während das Video seitlich gleitet. Für Volumen in den Bildern „Tiefenvolumen“ einschalten',
'Яркость фона текущего кадра': 'Helligkeit des Hintergrunds im aktuellen Bild',
